#!/bin/bash\n\n# Cores para output\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\necho -e \"${BLUE}🚀 AI Platform - Setup Automático${NC}\\n\"\n\n# 1. Verifica se Docker está instalado\necho -e \"${YELLOW}[1/5] Verificando Docker...${NC}\"\nif ! command -v docker &> /dev/null; then\n    echo -e \"${RED}❌ Docker não está instalado!${NC}\"\n    echo \"Baixe em: https://www.docker.com/products/docker-desktop\"\n    exit 1\nfi\necho -e \"${GREEN}✓ Docker encontrado${NC}\\n\"\n\n# 2. Copia .env.example para .env se não existir\necho -e \"${YELLOW}[2/5] Configurando ambiente...${NC}\"\nif [ ! -f .env ]; then\n    if [ -f .env.example ]; then\n        cp .env.example .env\n        echo -e \"${GREEN}✓ Arquivo .env criado${NC}\"\n    else\n        echo -e \"${YELLOW}⚠ .env.example não encontrado, criando .env vazio${NC}\"\n        touch .env\n    fi\nelse\n    echo -e \"${GREEN}✓ Arquivo .env já existe${NC}\"\nfi\necho \"\"\n\n# 3. Inicia os containers\necho -e \"${YELLOW}[3/5] Iniciando containers Docker...${NC}\"\ndocker-compose up -d\necho -e \"${GREEN}✓ Containers iniciados${NC}\\n\"\n\n# 4. Aguarda o banco ficar pronto\necho -e \"${YELLOW}[4/5] Aguardando banco de dados ficar pronto...${NC}\"\nsleep 10\necho -e \"${GREEN}✓ Banco pronto${NC}\\n\"\n\n# 5. Roda migrations\necho -e \"${YELLOW}[5/5] Rodando migrations...${NC}\"\ndocker-compose exec -T backend npm run migrate\necho -e \"${GREEN}✓ Migrations concluídas${NC}\\n\"\n\n# Seed opcional\nread -p \"Deseja popular o banco com dados de teste? (s/n) \" -n 1 -r\necho\nif [[ $REPLY =~ ^[Ss]$ ]]; then\n    echo -e \"${YELLOW}Rodando seed...${NC}\"\n    docker-compose exec -T backend npm run seed\n    echo -e \"${GREEN}✓ Dados de teste adicionados${NC}\"\n    echo -e \"${BLUE}📝 Login padrão:${NC}\"\n    echo \"   Email: test@example.com\"\n    echo \"   Senha: password\"\nfi\n\necho \"\"\necho -e \"${GREEN}════════════════════════════════════════${NC}\"\necho -e \"${GREEN}✅ Setup concluído com sucesso!${NC}\"\necho -e \"${GREEN}════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${BLUE}🌐 Acesse:${NC}\"\necho \"   Frontend:  http://localhost:3000\"\necho \"   Backend:   http://localhost:5000\"\necho \"   Database:  localhost:5432\"\necho \"\"\necho -e \"${BLUE}📋 Comandos úteis:${NC}\"\necho \"   Ver logs:      docker-compose logs -f\"\necho \"   Parar:         docker-compose down\"\necho \"   Reiniciar:     docker-compose restart\"\necho \"\"\n"